KG42.register("rules-bffb0ed9eba3a2709f9396c1",{"id":"23-hierarchical_market_structure::v141-c-R009","paper":"23-hierarchical_market_structure","record":{"rule_id":"v141-c-R009","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"The LA's purchase from the WEM and equal-volume resale to the DNEM are conditional on the DNEM price exceeding the WEM bus LMP. Scope: LA role 1: buying electricity from the WEM and selling the same volume to the DNEM. Condition: The LMP at the LA's bus in the WEM is lower than the electricity price in the DNEM. The LA's purchase from the DNEM and equal-volume resale to the WEM are conditional on the DNEM clearing price being below the WEM bus LMP. Scope: LA role 2: purchasing electricity from the DNEM and selling the same volume to the WEM. Condition: The MCP in the DNEM is lower than the LMP at the LA's bus in the WEM.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["execution.energy_trade","pricing.local"],"E":[{"edge_id":"v141-c-R009-E001","source":"execution.energy_trade","target":"pricing.local","type":"conditional_on","constraint_ids":["v141-c-R009-C001","v141-c-R009-C002"],"evidence_ids":["v141-b-g01-E009"]}],"omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"LA role 1: buying electricity from the WEM and selling the same volume to the DNEM. | LA role 2: purchasing electricity from the DNEM and selling the same volume to the WEM.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E009"]},"x":[{"variable_id":"v141-c-R009-x001","symbol":"P_l^{imp}","meaning":"Power imported to the DNEM by LA l; in role 1 this is the volume bought in the WEM and sold to the DNEM.","kind":"operational","domain":"real-valued power quantity [MW] within the source's stated import bounds","unit":"MW","indices":["l"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E009","v141-b-g01-E010"]},{"variable_id":"v141-c-R009-x002","symbol":"P_l^{exp}","meaning":"Power exported from the DNEM by LA l; in role 2 this is the volume purchased in the DNEM and sold to the WEM.","kind":"operational","domain":"real-valued power quantity [MW] within the source's stated export bounds","unit":"MW","indices":["l"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E009","v141-b-g01-E011"]}],"theta":[{"parameter_id":"v141-c-R009-theta001","symbol":"LMP'_o","meaning":"WEM locational marginal price at bus o, including the LA's bus o in B_l^o; used as the WEM price in the LA role-selection comparison.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/MWh","indices":["o"],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E014"]},{"parameter_id":"v141-c-R009-theta002","symbol":"\\lambda_0","meaning":"DNEM market clearing price (MCP), i.e. the Lagrange multiplier on the DNEM generation-load balance constraint; used as the DNEM price in the LA role-selection comparison.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/MWh","indices":[],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E011","v141-b-g01-E015"]}],"phi":[{"constraint_id":"v141-c-R009-C001","kind":"logical","role":"core","statement":"The LA's purchase from the WEM and equal-volume resale to the DNEM are conditional on the DNEM price exceeding the WEM bus LMP. Scope: LA role 1: buying electricity from the WEM and selling the same volume to the DNEM. Condition: The LMP at the LA's bus in the WEM is lower than the electricity price in the DNEM.","expression":"\\left( LMP'_{o} \u003c \\lambda_0 \\right) \\implies \\left( P_l^{imp} > 0 \\right), \\quad o \\in B_l^o","formalization_origin":"equivalent_translation","template_id":null,"members":["execution.energy_trade","pricing.local"],"variable_refs":["v141-c-R009-x001"],"parameter_refs":["v141-c-R009-theta001","v141-c-R009-theta002"],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E010","v141-b-g01-E014","v141-b-g01-E015"]},{"constraint_id":"v141-c-R009-C002","kind":"logical","role":"core","statement":"The LA's purchase from the DNEM and equal-volume resale to the WEM are conditional on the DNEM clearing price being below the WEM bus LMP. Scope: LA role 2: purchasing electricity from the DNEM and selling the same volume to the WEM. Condition: The MCP in the DNEM is lower than the LMP at the LA's bus in the WEM.","expression":"\\left( \\lambda_0 \u003c LMP'_{o} \\right) \\implies \\left( P_l^{exp} > 0 \\right), \\quad o \\in B_l^o","formalization_origin":"equivalent_translation","template_id":null,"members":["execution.energy_trade","pricing.local"],"variable_refs":["v141-c-R009-x002"],"parameter_refs":["v141-c-R009-theta001","v141-c-R009-theta002"],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E011","v141-b-g01-E014","v141-b-g01-E015"]}],"pi":[{"evidence_id":"v141-b-g01-E009","location":{"location_id":"src-fbc18f73e3-p04-c1r1__v141-a-M01-participation","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"MANSHADI AND KHODAYAR: HIERARCHICAL ELECTRICITY MARKET STRUCTURE electricity from the WEM and sell t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"Each LA participates in the WEM and the DNEM. The LA acts as a broker playing two different roles: 1) buy electricity from the WEM and sell the same volume to the DNEM, if the LMP on the LAs bus in the WEM is lower than that in the DNEM; and 2) purchase electricity from the DNEM and sell the same volume to the WEM, if the MCP in the DNEM is lower than the LMP on the LAs bus in the WEM."},{"evidence_id":"v141-b-g01-E000","location":{"location_id":"src-fbc18f73e3-p01-c1r4__v141-a-M01-participation","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"Variables Pj Generation dispatch of generator j [MW]. Pm Generation dispatch of microgrid m [MW]. Pe","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"P_j Generation dispatch of generator j [MW]. P_m Generation dispatch of microgrid m [MW]. P_l^{exp}, P_l^{imp} Power “exported from”/“imported to” distribution network electricity market (DNEM) by LA l [MW]. R_j Payoff function of GENCO j [$]. R_m Payoff function of microgrid m [$]. R_l, R'_l Payoff function of LA l in the DNEM/wholesale electricity market (WEM) [$]. \\rho_m, \\rho_l Bidding vector of microgrid m/LA l in the DNEM [$/MW]. \\rho'_j, \\rho'_l Bidding vector of GENCO j/LA l in the WEM [$/MW]. \\psi_m, \\psi_l Bidding strategy vector of microgrid m/LA l in the DNEM. \\psi'_j, \\psi'_l Bidding strategy vector of unit j of GENCO i/LA l in the WEM. \\lambda_0, \\lambda'_0, \\lambda_b^{'+}, \\lambda_b^{'-} Lagrange multipliers. B_j^o, B_l^o Set of buses o corresponds to the market participants j and l. \\bar{F}_b, \\underline{F}_b Minimum/maximum limits for power flow in branch b [MW]. P^D Total demand in the distribution network [MW]. P_o^{'D} Demand on bus o in the WEM [MW]. \\bar{P}_l^{exp}, \\underline{P}_l^{exp} Minimum/maximum power exported from the DNEM by LA l [MW]. \\bar{P}_l^{imp}, \\underline{P}_l^{imp} Minimum/maximum power imported to the DNEM by LA l [MW]. \\bar{P}_{(.)}, \\underline{P}_{(.)} Minimum/maximum generation dispatch [MW]. SF_b^o Shift factor of branch b with respect to injection at bus o. \\alpha(.), \\beta(.), \\gamma(.) Coefficients for generation cost function. \\bar{\\psi}(.), \\underline{\\psi}(.) Upper/lower limit of the bidding strategy vector in the DNEM. \\bar{\\psi}'(.), \\underline{\\psi}'(.) Upper/lower limit of the bidding strategy vector in the WEM."},{"evidence_id":"v141-b-g01-E010","location":{"location_id":"src-fbc18f73e3-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in","equation_id":"(7)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Considering role “1,” LA l maximizes the payoff function which is shown in (7), subjected to the bidding vector constraint (8). Here, LMP' is the marginal price of electricity on the LAs bus in the WEM which is determined as the cost of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in (9)\nR_l = \\max_{\\psi_l,P_l^{imp}} \\left[ \\left(\\lambda_0 - \\sum_{o\\in B_l^o} LMP'_o\\right) P_l^{imp} \\right] \\tag{7}\n\\underline{\\psi}_l \\le \\psi_l \\le \\bar{\\psi}_l \\tag{8}\n\\rho_l = \\psi_l * \\sum_{o\\in B_l^o} LMP'_o. \\tag{9}"},{"evidence_id":"v141-b-g01-E011","location":{"location_id":"src-fbc18f73e3-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in","equation_id":"(10)-(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"R'_l = \\max_{\\psi'_l,P_l^{exp}} \\left[ \\left(\\sum_{o\\in B_l^o} LMP'_o - \\lambda_0\\right) P_l^{exp} \\right] \\tag{10}\n\\underline{\\psi}'_l \\le \\psi'_l \\le \\bar{\\psi}'_l \\tag{11}\n\\rho'_l = \\psi'_l * \\lambda_0. \\tag{12}\nConsidering role “2,” the LA l maximizes the payoff function which is shown in (10), subjected to the constraints on the bidding vector (11). The MCP (\\lambda_0) in the DNEM is the marginal cost of providing electricity to the WEM. The bidding vector of LA l in the WEM is shown in (12)."},{"evidence_id":"v141-b-g01-E014","location":{"location_id":"src-fbc18f73e3-p04-c1r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"II-D WEM Clearing Process","anchor_text":"Fb ≤⎝ SFb.Pj + SFb.Pl ⎠ Th o∈Boj o∈Bol lev in , λ′− −SFob.PDo − SFob.Pimpl ≤¯Fb ∀b, λ′+b b in o∈Bol ","equation_id":"(18)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"As shown in (18), the Lagrangian multipliers associated with the load balance and transmission line capacity constraints are employed to calculate the LMPs on each bus in the WEM.\nLMP'_o = \\lambda'_0 + \\sum_b (SF_b^o)^T \\cdot (\\lambda_b^{'+} - \\lambda_b^{'-}). \\tag{18}"},{"evidence_id":"v141-b-g01-E015","location":{"location_id":"src-fbc18f73e3-p04-c2r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"II-E DNEM Clearing Process","anchor_text":"y As min ρm ∗Pm + ρl ∗Pimpl (19) m l 7) s.t. Pm + Pimpl = PD + Pexpl λ0 (20) m l l 8) P m ≤Pm ≤¯Pm ∀","equation_id":"(19)-(22)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The DNO minimizes the operational cost of distribution network as shown by\n\\min \\sum_m \\rho_m * P_m + \\sum_l \\rho_l * P_l^{imp} \\tag{19}\ns.t. \\sum_m P_m + \\sum_l P_l^{imp} = P^D + \\sum_l P_l^{exp} \\quad \\lambda_0 \\tag{20}\n\\underline{P}_m \\le P_m \\le \\bar{P}_m \\quad \\forall m \\tag{21}\n\\underline{P}_l^{imp} \\le P_l^{imp} \\le \\bar{P}_l^{imp} \\quad \\forall l. \\tag{22}\nThe load balance in the distribution network is shown in (20). The constraints on the awarded generation for microgrids and the imported power by the LA are shown in (21) and (22), respectively. Here, \\lambda_0 is the Lagrangian multiplier for the generation and load balance constraint in the distribution network as it is assumed that the electricity delivery is not limited by the line congestions."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-coordination","v141-a-M01-participation"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E009","quote":"The LA acts as a broker playing two different roles: 1) buy electricity from the WEM and sell the same volume to the DNEM, if the LMP on the LAs bus in the WEM is lower than that in the DNEM;"}],[{"evidence_id":"v141-b-g01-E009","quote":"2) purchase electricity from the DNEM and sell the same volume to the WEM, if the MCP in the DNEM is lower than the LMP on the LAs bus in the WEM."}]],"C2_formalization":{"graph_sha256":"2ae935dc00eee57df499834d4f5f9d9927606aabf9d9ef974fba62f4f47f090f","applicability":"formalized","reason":"The source text v141-b-g01-E009 states two explicit price-comparison conditionals for the LA's roles. I formalize the WEM bus price as LMP'_o (defined by v141-b-g01-E014) and the DNEM price as lambda_0, the DNEM MCP (v141-b-g01-E011 and v141-b-g01-E015), and use the source's P_l^{imp}/P_l^{exp} as the role-specific DNEM trade volumes. The implications encode the prose 'if ... buy/sell' as trade activation; the positive-volume condition is an equivalent translation of buying/selling, not a separately printed source equation. B evidence remains unreviewed.","bindings":[{"object_id":"v141-c-R009-x001","node_ids":["execution.energy_trade"],"edge_ids":["v141-c-R009-E001"],"rationale":"P_l^{imp} is the LA's DNEM import/trade volume in role 1. The frozen conditional_on edge v141-c-R009-E001 connects the execution.energy_trade execution function to pricing.local, which supplies the role-selection price condition."},{"object_id":"v141-c-R009-x002","node_ids":["execution.energy_trade"],"edge_ids":["v141-c-R009-E001"],"rationale":"P_l^{exp} is the LA's DNEM export/trade volume in role 2. The frozen conditional_on edge v141-c-R009-E001 connects the execution.energy_trade execution function to pricing.local, which supplies the role-selection price condition."},{"object_id":"v141-c-R009-theta001","node_ids":["pricing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"LMP'_o is the WEM bus price used in the conditional comparison. It is supplied by pricing.local and reaches the energy-trade execution relation through the frozen conditional_on edge v141-c-R009-E001."},{"object_id":"v141-c-R009-theta002","node_ids":["pricing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"lambda_0 is the DNEM MCP used in the conditional comparison. It is supplied by pricing.local and reaches the energy-trade execution relation through the frozen conditional_on edge v141-c-R009-E001."},{"object_id":"v141-c-R009-C001","node_ids":["execution.energy_trade","pricing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"Formalizes source role 1: when the WEM bus LMP is below the DNEM MCP, the LA activates positive DNEM import, i.e. WEM purchase and equal-volume DNEM sale. The frozen edge v141-c-R009-E001 is the conditional_on relation between execution and pricing."},{"object_id":"v141-c-R009-C002","node_ids":["execution.energy_trade","pricing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"Formalizes source role 2: when the DNEM MCP is below the WEM bus LMP, the LA activates positive DNEM export, i.e. DNEM purchase and equal-volume WEM sale. The frozen edge v141-c-R009-E001 is the conditional_on relation between execution and pricing."}],"revision_requests":[]}},"quarantined_references":[]}});
